/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
/// The PurchTabel form extension
/// </summary>
[ExtensionOf(FormStr(PurchTable))]
final class METPurchTableForm_Extension
{   
}

Method.Source:
    /// <summary>
    /// Added by kavya on 18/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// TO update the change reason code for all the PO Line
    /// </summary>
    /// <param name = "_control"> Form control </param>
    public void METChangeReasonCodeLookup(FormStringControl _control)
    {
        SysTableLookup sysTableLookup = sysTableLookup::newParameters(tableNum(METPOChangeReasonCodeSetup), _control,true);

        sysTableLookup.addLookupfield(fieldNum(METPOChangeReasonCodeSetup, ChangeReasonCode));
        sysTableLookup.addLookupfield(fieldNum(METPOChangeReasonCodeSetup, ChangeReasonDesc));
        sysTableLookup.addLookupfield(fieldNum(METPOChangeReasonCodeSetup, ChangeReasonCodeType));

        sysTableLookup.performFormLookup();
    }

    /// <summary>
    ///  VM - CB199 - Added to disable the Purchase type field for all users
    /// </summary>
    internal void init()
    {
        next init();

        // VM - CB199 - Restrict PO & delete fields
        PurchTable_ds.object(fieldNum(Purchtable,PurchaseType)).enabled(NoYes::No); //Need to disable the PO type for all the users

        PurchLine purchLine = this.dataSource(formDataSourceStr(PurchTable, PurchLine)).cursor();
        PurchTable_ds.object(fieldNum(PurchTable, METIntercompanyTransferReplenishment)).allowEdit(purchLine.RecId == 0);

        // Bug 231840: CB501 - Disable Remove button for PO lines for ISP users
        // Hide/Show std button based on ISP user or not. Custom button will be managed with security configuration
        FormControl lineStripDelete = this.design().controlName(formControlStr(PurchTable, LineStripDelete)) as FormControl;
        lineStripDelete.visible(!METisISPUser());
    }
